13	func seed(t *testing.T, m *Memory, merchant string, n int) []string {
14		t.Helper()
15		ids := make([]string, 0, n)
16		for i := 0; i < n; i++ {
17			id := fmt.Sprintf("%s_pay_%03d", merchant, i)
18			p := payment.Payment{ID: id, MerchantID: merchant, Amount: money.MustNew(100, "USD"), Status: payment.StatusCreated, Version: 1}
19			if err := m.Create(context.Background(), p); err != nil {
20				t.Fatal(err)
21			}
22			ids = append(ids, id)
23		}
24		return ids
25	}
26	
27	func TestCreateGet(t *testing.T) {
28		m := NewMemory()
29		seed(t, m, "m1", 1)
30		p, err := m.Get(context.Background(), "m1_pay_000")
31		if err != nil || p.MerchantID != "m1" {
32			t.Fatalf("Get = %+v, %v", p, err)
33		}
34		if _, err := m.Get(context.Background(), "nope"); !errors.Is(err, payment.ErrNotFound) {
35			t.Fatalf("missing: %v", err)
36		}
37		if err := m.Create(context.Background(), p); !errors.Is(err, payment.ErrDuplicate) {
38			t.Fatalf("duplicate: %v", err)
39		}
40	}
41	
42	func TestUpdateOptimisticLocking(t *testing.T) {
43		ctx := context.Background()
44		m := NewMemory()
45		seed(t, m, "m1", 1)
46		p, _ := m.Get(ctx, "m1_pay_000")
47		stale := p
48		p.Status = payment.StatusPending
49		if err := m.Update(ctx, p); err != nil {
50			t.Fatal(err)
51		}
52		got, _ := m.Get(ctx, p.ID)
53		if got.Version != 2 || got.Status != payment.StatusPending {
54			t.Fatalf("after update: %+v", got)
55		}
56		stale.Status = payment.StatusDeclined
57		if err := m.Update(ctx, stale); !errors.Is(err, payment.ErrVersionConflict) {
58			t.Fatalf("stale update: %v", err)
59		}
60	}
61	
62	func TestListFirstPage(t *testing.T) {
63		m := NewMemory()
64		ids := seed(t, m, "m1", 5)
65		seed(t, m, "m2", 3)
66		got, next, err := m.ListByMerchant(context.Background(), "m1", payment.Page{Limit: 2})
67		if err != nil {
68			t.Fatal(err)
69		}
70		if len(got) != 2 || got[0].ID != ids[0] || got[1].ID != ids[1] || next == "" {
71			t.Fatalf("page = %v next %q", got, next)
72		}
73	}
74	
75	func TestListLimits(t *testing.T) {
76		m := NewMemory()
77		seed(t, m, "m1", 150)
78		tests := []struct {
79			limit, want int
80		}{
81			{0, 20},
82			{5, 5},
83			{500, 100},
84		}
85		for _, tt := range tests {
86			got, _, err := m.ListByMerchant(context.Background(), "m1", payment.Page{Limit: tt.limit})
87			if err != nil || len(got) != tt.want {
88				t.Errorf("limit %d: got %d items, err %v", tt.limit, len(got), err)
89			}
90		}
91		if _, _, err := m.ListByMerchant(context.Background(), "m1", payment.Page{Limit: -1}); !errors.Is(err, payment.ErrInvalidInput) {
92			t.Errorf("negative limit: %v", err)
93		}
94		if _, _, err := m.ListByMerchant(context.Background(), "m1", payment.Page{Cursor: "!!"}); !errors.Is(err, payment.ErrInvalidCursor) {
95			t.Errorf("bad cursor: %v", err)
96		}
97	}

