func TestListFirstPage(t *testing.T) {
	m := NewMemory()
	ids := seed(t, m, "m1", 5)
	seed(t, m, "m2", 3)
	got, next, err := m.ListByMerchant(context.Background(), "m1", payment.Page{Limit: 2})
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 2 || got[0].ID != ids[0] || got[1].ID != ids[1] || next == "" {
		t.Fatalf("page = %v next %q", got, next)
	}
}

func TestListWalkAllPages(t *testing.T) {
	ctx := context.Background()
	totals := []int{0, 1, 2, 19, 20, 21, 50, 100, 1000}
	limits := []int{0, 1, 2, 7, 20, 50, 100, 250}

	for _, total := range totals {
		m := NewMemory()
		seed(t, m, "other", 5)
		want := seed(t, m, "m_204", total)
		seed(t, m, "other2", 5)

		for _, limit := range limits {
			t.Run(fmt.Sprintf("total=%d/limit=%d", total, limit), func(t *testing.T) {
				var got []string
				cursor := ""
				pages := 0
				for {
					ps, next, err := m.ListByMerchant(ctx, "m_204", payment.Page{Cursor: cursor, Limit: limit})
					if err != nil {
						t.Fatalf("page %d: %v", pages, err)
					}
					pages++
					if total > 0 && len(ps) == 0 {
						t.Fatalf("empty trailing page %d (cursor %q)", pages, cursor)
					}
					for _, p := range ps {
						got = append(got, p.ID)
					}
					if next == "" {
						break
					}
					if pages > total+2 {
						t.Fatalf("pagination did not terminate after %d pages", pages)
					}
					cursor = next
				}
				if len(got) != len(want) {
					t.Fatalf("collected %d payments, want %d", len(got), len(want))
				}
				for i := range want {
					if got[i] != want[i] {
						t.Fatalf("item %d = %s, want %s", i, got[i], want[i])
					}
				}
			})
		}
	}
}

