	if len(page.Data) != 2 || page.NextCursor == "" {
		t.Fatalf("page %+v", page)
	}
	if rec := a.do("GET", "/merchants/m_1/payments?limit=x", ""); rec.Code != http.StatusBadRequest {
		t.Fatalf("bad limit status %d", rec.Code)
	}
}

func TestListPaymentsReconciliationPaging(t *testing.T) {
	a := newTestAPI(t)
	const total = 1000
	want := make([]string, 0, total)
	for i := 0; i < total; i++ {
		rec := a.do("POST", "/payments", `{"merchant_id":"m_204","amount":"1.00","currency":"USD"}`)
		if rec.Code != http.StatusCreated {
			t.Fatalf("create %d: %d %s", i, rec.Code, rec.Body)
		}
		want = append(want, decode[paymentResponse](t, rec).ID)
	}

	for _, limit := range []string{"50", "1", "37", "100"} {
		t.Run("limit="+limit, func(t *testing.T) {
			var got []string
			cursor := ""
			for {
				path := "/merchants/m_204/payments?limit=" + limit
				if cursor != "" {
					path += "&cursor=" + cursor
				}
				rec := a.do("GET", path, "")
				if rec.Code != http.StatusOK {
					t.Fatalf("status %d: %s", rec.Code, rec.Body)
				}
				page := decode[listResponse](t, rec)
				if len(page.Data) == 0 {
					t.Fatalf("unexpected empty page for cursor %q", cursor)
				}
				for _, p := range page.Data {
					got = append(got, p.ID)
				}
				if page.NextCursor == "" {
					break
				}
				cursor = page.NextCursor
			}
			if len(got) != len(want) {
				t.Fatalf("got %d payments, want %d", len(got), len(want))
			}
			for i := range want {
				if got[i] != want[i] {
					t.Fatalf("item %d = %s, want %s", i, got[i], want[i])
				}
			}
		})
	}
}

